\end{aligned}
$$

Now collect each component:

$$
\begin{aligned}
(\nabla(fg))_{x}&=g f_{x}+f g_{x} \\ &=(2 x^{2} + y^{2})(- 2 e^{- 2 x - 2 y}) \\ &\quad+(e^{- 2 x - 2 y})(4 x) \\ &=- 2 \left(2 x^{2} + y^{2}\right) e^{- 2 x - 2 y} \\ &\quad+(4 x e^{- 2 x - 2 y}) \\ &=2 \left(- 2 x^{2} + 2 x - y^{2}\right) e^{- 2 x - 2 y}
\end{aligned}
$$

$$
\begin{aligned}
(\nabla(fg))_{y}&=g f_{y}+f g_{y} \\ &=(2 x^{2} + y^{2})(- 2 e^{- 2 x - 2 y}) \\ &\quad+(e^{- 2 x - 2 y})(2 y) \\ &=- 2 \left(2 x^{2} + y^{2}\right) e^{- 2 x - 2 y} \\ &\quad+(2 y e^{- 2 x - 2 y}) \\ &=2 \left(- 2 x^{2} - y^{2} + y\right) e^{- 2 x - 2 y}
\end{aligned}
$$

Thus the gradient is

$$
\begin{aligned}&2 \left(- 2 x^{2} + 2 x - y^{2}\right) e^{- 2 x - 2 y}\mathbf i \\ &{}+2 \left(- 2 x^{2} - y^{2} + y\right) e^{- 2 x - 2 y}\mathbf j\end{aligned}
